package com.example.proyectolp.service;
import com.example.proyectolp.model.DailyMission;import com.example.proyectolp.repository.DailyMissionRepository;import java.time.*;import java.util.*;
public class MissionService {private record Spec(String code,String text,int target,int xp){}private static final List<Spec> POOL=List.of(new Spec("HABITS_2","Completa 2 hábitos hoy",2,30),new Spec("TASKS_2","Completa 2 tareas",2,40),new Spec("STAGE_1","Completa una etapa",1,30),new Spec("WORKOUT_1","Finaliza una sesión",1,30),new Spec("FINANCE_1","Registra un movimiento financiero",1,20));private final DailyMissionRepository repo;private final Clock clock;public MissionService(SupabaseService db,Clock c){repo=new DailyMissionRepository(db);clock=c;}private LocalDate currentDate(){return LocalDate.now(clock.withZone(ZoneId.of("America/Bogota")));}public List<DailyMission> today()throws Exception{LocalDate d=currentDate();List<DailyMission> existing=repo.list(d);if(existing.size()<3){List<Spec> ordered=new ArrayList<>(POOL);Collections.rotate(ordered,-Math.floorMod(d.toEpochDay(),POOL.size()));for(Spec x:ordered){if(existing.size()>=3)break;if(existing.stream().noneMatch(m->m.code.equals(x.code)))repo.create(d,x.code,x.text,x.target,x.xp);existing=repo.list(d);}}return existing;}public int event(String code,XpService xp)throws Exception{LocalDate d=currentDate();today();List<DailyMission> before=repo.list(d);repo.progress(d,code,1);List<DailyMission> after=repo.list(d);int earned=0;for(DailyMission m:after)if(m.code.equals(code)&&m.completed&&before.stream().noneMatch(b->b.id==m.id&&b.completed)&&xp.grant(m.xp_reward,"Misión completada","xp:mission:"+d+":"+m.code))earned+=m.xp_reward;return earned;}}
